import { expect, expectStatus, test } from "../../fixtures";

type VendorBody = { id: string; name: string };
type ErrorBody = { error: { code: string } };

test(
  "a vendor cannot be renamed to another vendor's name, whatever the case",
  { tag: "@LIF-10" },
  async ({ apiAs }) => {
    // Arrange: unique suffix so parallel tests sharing one database don't collide
    const member = await apiAs("member");
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const atlasName = `Atlas Freight ${suffix}`;
    const borealisName = `Borealis Freight ${suffix}`;

    const vendorPayload = (name: string) => ({
      name,
      category: "logistics",
      contact_email: `ops+${suffix}@example.test`,
    });

    const atlas = await expectStatus<VendorBody>(
      await member.post("/api/vendors", { data: vendorPayload(atlasName) }),
      201,
    );
    const borealis = await expectStatus<VendorBody>(
      await member.post("/api/vendors", { data: vendorPayload(borealisName) }),
      201,
    );

    // Act: rename Borealis to Atlas's name in different casing
    const response = await member.patch(`/api/vendors/${borealis.id}`, {
      data: { name: atlasName.toUpperCase() },
    });

    // Assert: rejected with a conflict and the documented error code
    const body = await expectStatus<ErrorBody>(response, 409);
    expect(body.error.code).toBe("vendor_name_taken");

    // Assert: Borealis keeps its original name
    const current = await expectStatus<VendorBody>(
      await member.get(`/api/vendors/${borealis.id}`),
      200,
    );
    expect(current.name).toBe(borealisName);

    // Assert: Atlas is untouched as well
    const atlasCurrent = await expectStatus<VendorBody>(
      await member.get(`/api/vendors/${atlas.id}`),
      200,
    );
    expect(atlasCurrent.name).toBe(atlasName);
  },
);
